-- BREAKCORE CAT SKY - iPad/Delta All-in-One
local L=game:GetService("Lighting")
local G=getcustomasset or getsynasset
if not writefile or not G then return end
local B=[[]]
local A='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local T={} for i=1,#A do T[A:sub(i,i)]=i-1 end
local function D(s) local o={} for i=1,#s,4 do local a=T[s:sub(i,i)]or 0 local b=T[s:sub(i+1,i+1)]or 0 local c=T[s:sub(i+2,i+2)] local d=T[s:sub(i+3,i+3)] local v=a*262144+b*4096+(c or 0)*64+(d or 0) o[#o+1]=string.char(math.floor(v/65536)%256) if c then o[#o+1]=string.char(math.floor(v/256)%256) end if d then o[#o+1]=string.char(v%256) end end return table.concat(o) end
writefile('breakcore_music.jpeg',D(B))
local x=G('breakcore_music.jpeg')
local s=L:FindFirstChild('BreakcoreCatSky') or Instance.new('Sky') s.Name='BreakcoreCatSky' s.Parent=L
local function apply() s.SkyboxBk=x s.SkyboxDn=x s.SkyboxFt=x s.SkyboxLf=x s.SkyboxRt=x s.SkyboxUp=x end
apply() for _,t in ipairs({.5,1.5,3,6,10}) do task.delay(t,apply) end
